OPTIONAL MATCH (a)-[r]-(e:__Entity__)
OPTIONAL MATCH (a)-[:FROM_CHUNK]->(c:Chunk)-[:FROM_DOCUMENT]->(d:Document)
WITH a, r, e, c, d,
     CASE
       WHEN e IS NOT NULL AND (toLower(e.name) CONTAINS 't.j. hockenson' OR toLower(e.name) CONTAINS 'tj hockenson' OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS 't.j. hockenson' OR toLower(alias) CONTAINS 'tj hockenson')) THEN 0
       WHEN e IS NOT NULL AND (toLower(e.name) CONTAINS 'dalton kincaid' OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS 'dalton kincaid')) THEN 1
       WHEN e IS NOT NULL AND 'Event' IN labels(e) AND (toLower(e.name) CONTAINS 'saturday' OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS 'saturday')) THEN 2
       ELSE 3
     END AS relevance
RETURN DISTINCT a.name AS article, a.published_on AS published_on,
       e.name AS connected_entity, labels(e) AS entity_labels,
       type(r) AS relationship, d.title AS evidence_document, c.index AS evidence_chunk,
