    any(term IN ['withdrawal', 'trading revenue', 'board', 'fraud', 'personal gain', 'enrichment'] WHERE toLower(coalesce(a.title, '')) CONTAINS term OR toLower(coalesce(a.name, '')) CONTAINS term)
